/**
 * The NFL's official YouTube highlights upload for each game, keyed like
 * game-notes.ts: `<pair slug>/<game segment>`. The data is
 * data/matchup/game-videos.json, generated by scripts/find-game-videos.mjs,
 * which says how each one was checked; do not edit it by hand. A hand-written
 * video in game-notes.ts wins over this file.
 *
 * Read on first use and again whenever the file's mtime changes. A missing
 * file is no videos; one that does not parse keeps the last good read.
 */

import fs from "node:fs";
import { dataPath } from "../data-dir";
import type { GameVideo } from "./game-notes";

const FILE = dataPath("matchup", "game-videos.json");

let cache: { mtimeMs: number; videos: Record<string, GameVideo> } | null = null;

/** Every scanned upload, by `<pair slug>/<game segment>`. */
export function gameVideos(): Record<string, GameVideo> {
  let mtimeMs: number;
  try {
    mtimeMs = fs.statSync(FILE).mtimeMs;
  } catch {
    return {};
  }
  if (cache && cache.mtimeMs === mtimeMs) return cache.videos;
  try {
    cache = { mtimeMs, videos: JSON.parse(fs.readFileSync(FILE, "utf8")) as Record<string, GameVideo> };
  } catch {
    cache = { mtimeMs, videos: cache?.videos ?? {} };
  }
  return cache.videos;
}
